<script setup lang="ts">import { computed } from 'vue'; import { useRoute } from 'vue-router'; import { useAppStore } from '@/stores/app'; import CategoryTabs from '@/components/category/CategoryTabs.vue'; const route=useRoute(); const app=useAppStore(); const category=computed(()=>app.categories.find(p=>p.id===route.params.id))</script>
<template><div class="page category-page" v-if="category"><header class="category-header"><div class="category-icon large" :style="{background:category.color}">{{category.key[0]}}</div><div><p class="eyebrow">{{category.key}} category</p><h1>{{category.name}}</h1><p>{{category.description}}</p></div></header><CategoryTabs :category-id="category.id"/><RouterView :category="category"/></div><div v-else class="page"><div class="empty-state"><h2>Category not found</h2><RouterLink class="btn" to="/categories">Back to categories</RouterLink></div></div></template>
